document.addEventListener("DOMContentLoaded", () => {

const select = document.getElementById("selectEstacion");

if (!select) return;

select.addEventListener("change",
async function () {

const idEstacion = this.value;

try {

const response = await axios.post("/switch-estacion", {id_estacion : idEstacion});

if (response.data.ok) {
location.reload();
}

} catch (error) {
console.error(error);
}

}
);

});